insert into public.ai_knowledge (kind, area, country_code, topic, title, summary, source_name, source_url, license, lang, status) values
('management','legal','BR','abrir_empresa','Abrir una empresa en Brasil: Redesim, CNPJ, Junta Comercial y alvará',
$k$En Brasil la apertura pasa por la Redesim, el sistema que integra a los organismos federales, estaduales y municipales, en tres etapas: consulta de viabilidad (confirma si la actividad puede ejercerse en la dirección elegida y si corresponde el encuadre como ME o EPP), inscripción con registro en la Junta Comercial del estado y obtención del CNPJ en la Receita Federal, y licenciamiento. El documento que constituye la empresa es el contrato social, que puede usar el modelo estándar de la Junta Comercial. Con el CNPJ se tramitan la inscripción estadual y municipal y el alvará de funcionamiento con licencias específicas (Vigilancia Sanitaria, bomberos, etc.); las actividades de bajo riesgo están dispensadas de alvará. Dificultades frecuentes: requisitos distintos por estado y municipio, elegir mal el régimen (Simples Nacional, Lucro Presumido o Real) y licencias que demoran la operación. Dónde confirmar: portal oficial de la Redesim en gov.br/empresas-e-negocios (sección Abrir CNPJ).$k$,
'gov.br, Redesim: Abrir CNPJ','https://www.gov.br/empresas-e-negocios/pt-br/redesim/abrir-cnpj',
'Información oficial del portal gov.br y fuentes de apoyo (Agência Sebrae, Agilize); no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','operacion','BR','obligaciones_laborales','Obligaciones del empleador en Brasil: eSocial, FGTS, INSS y beneficios',
$k$Toda empresa con uno o más empleados debe usar el eSocial, el sistema que unifica las obligaciones fiscales, previsionales y laborales (Decreto 8.373/2014). La admisión debe registrarse hasta el día antes de que el trabajador empiece. El empleador deposita el FGTS, que equivale a 8 % del salario bruto (2 % en contrato de aprendizaje), y las empresas que no están en el Simples Nacional pagan además el INSS patronal de alrededor de 20 % sobre la nómina más contribuciones de riesgo (RAT) y terceros. Corresponden 30 días de vacaciones con un tercio adicional y el 13º salario. Atrasos, falta de registro o errores en los valores generan multas (una fuente indica una multa mínima de R$ 800 para ME y EPP) y reclamos laborales retroactivos. Dónde confirmar: portal oficial del eSocial en gov.br/esocial y la Caixa Econômica Federal para el FGTS.$k$,
'gov.br, eSocial: conoce el eSocial','https://www.gov.br/esocial/pt-br/centrais-de-conteudo',
'Información oficial del eSocial y fuentes de apoyo (Jornal Contábil, Meu Contador Online); no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador o abogado laboral.','es','draft'),
('management','legal','MX','abrir_empresa','Abrir una empresa en México: SAS en línea, RFC y permisos',
$k$En México la Sociedad por Acciones Simplificada (SAS) se constituye por el portal gob.mx/tuempresa de la Secretaría de Economía, en línea, de forma gratuita y en cuestión de horas, y limita la responsabilidad de los socios al monto de su aportación. Solo pueden formarla personas físicas, y se requiere RFC y firma electrónica (e.firma); la autorización de uso de la denominación vale 180 días. Otras opciones son la Sociedad Anónima, la SRL o trabajar como persona física con actividad empresarial sin constituir sociedad. Una vez constituida, la empresa necesita su inscripción en el RFC del SAT, licencias municipales según el giro y el alta patronal en el IMSS si contrata trabajadores. Los porcentajes y trámites del IMSS deben confirmarse en su portal. Dónde confirmar: gob.mx/tuempresa (Secretaría de Economía), SAT e IMSS.$k$,
'Secretaría de Economía, Sociedad por Acciones Simplificada (SAS)','https://www.gob.mx/cms/uploads/attachment/file/318218/2.1.1_Sociedad_por_Acciones_Simplificadas__SAS_.pdf',
'Material informativo oficial de la Secretaría de Economía de México y fuentes de apoyo (BBVA, Nafin); no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador o abogado.','es','draft'),
('management','legal','EC','abrir_empresa','Abrir una empresa en Ecuador: Superintendencia de Compañías, RUC y patente',
$k$En Ecuador las compañías se constituyen en el portal de constitución electrónica de la Superintendencia de Compañías, Valores y Seguros, que incluye la escritura por el notario, la inscripción en el Registro Mercantil y la generación del RUC por el SRI. La Sociedad por Acciones Simplificada (SAS) permite constituir con un solo accionista y con un capital de pocos dólares, y su constitución tarda entre dos y cinco días según la prensa, frente a casi dos meses en el trámite tradicional. Después hay que obtener los permisos y pagar la patente municipal en el cantón (algunas ciudades piden licencia LUAE) y afiliar a los trabajadores al IESS; una fuente de apoyo cita un aporte patronal de 11,15 % de la nómina, a confirmar. Dónde confirmar: portal de la Superintendencia de Compañías (supercias.gob.ec), SRI e IESS.$k$,
'GOB.EC, Constitución electrónica de compañías (Superintendencia de Compañías)','https://www.gob.ec/scvs/tramites/constitucion-electronica-companias',
'Información oficial de gob.ec y fuentes de apoyo (Primicias, CuantoMeCuesta); no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador o abogado.','es','draft'),
('management','legal','UY','abrir_empresa','Abrir una empresa en Uruguay: Empresa en el Día y SAS',
$k$En Uruguay el régimen Empresa en el Día permite que la sociedad quede inscripta y publicada ante BPS, DGI, DGR, AIN e IMPO en un solo trámite, y en su etapa inicial los socios solo pueden aportar dinero. La Sociedad por Acciones Simplificada (SAS) se inscribe ante la DGI y el BPS por los servicios en línea, y sus administradores aportan a la seguridad social por una única actividad patronal (Ley 19.820). Quien contrata personal debe inscribirse además en el Ministerio de Trabajo (MTSS) y en el Banco de Seguros del Estado (BSE). Una fuente de apoyo cita aportes patronales de 7,5 % jubilatorio, 5 % Fonasa y 3,27 % BSE, además del aguinaldo y el salario vacacional; confirmar valores. Dónde confirmar: gub.uy/tramites, DGI y BPS.$k$,
'gub.uy, inscripción de una SAS en formación (DGI y BPS)','https://www.gub.uy/tramites/inscripcion-sociedad-acciones-simplificada-formacion-sas',
'Información oficial de gub.uy y fuentes de apoyo (Uruguay XXI, IMPO); no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador o abogado.','es','draft');